import json
import os
import subprocess
import threading
from queue import Queue

def read_results():
    if os.path.exists("results.jsonl"):
        with open("results.jsonl", "r") as f:
            return [json.loads(line) for line in f.readlines()]
    return []

def write_results(results):
    with open("results.jsonl", "a") as f:
        for res in results:
            f.write(json.dumps(res) + "\n")

def process_job(job_id, command, results_queue):
    try:
        process = subprocess.Popen(
            command,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True
        )
        output, _ = process.communicate()
        exit_code = process.returncode
        results_queue.put({
            "id": job_id,
            "exit_code": exit_code,
            "output": output
        })
    except Exception as e:
        results_queue.put({
            "id": job_id,
            "exit_code": -1,
            "output": str(e)
        })

def run_jobs(jobs, results):
    existing_jobs = {job["id"] for job in results}
    queue = Queue()
    active_threads = []

    for job in jobs:
        if job["id"] not in existing_jobs:
            thread = threading.Thread(
                target=process_job,
                args=(job["id"], job["command"], queue)
            )
            active_threads.append(thread)
            thread.start()

    while active_threads:
        for thread in active_threads:
            if not thread.is_alive():
                active_threads.remove(thread)
                if not active_threads:
                    break

    executed = 0
    skipped = 0
    while not queue.empty():
        result = queue.get()
        results.append(result)
        executed += 1

    for job in jobs:
        if job["id"] in existing_jobs:
            skipped += 1

    print(f"{executed} {skipped}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python jobrunner.py <jobs.json>")
        sys.exit(1)

    with open(sys.argv[1], "r") as f:
        jobs = json.load(f)

    results = read_results()
    run_jobs(jobs, results)
    write_results(results)

import json
import os
import subprocess
from concurrent.futures import ThreadPoolExecutor, as_completed
import sys

def load_results():
    if os.path.exists("results.jsonl"):
        with open("results.jsonl", "r") as f:
            return [json.loads(line) for line in f]
    return []

def save_results(results):
    with open("results.jsonl", "a") as f:
        for result in results:
            f.write(json.dumps(result) + "\n")

def process_job(job_id, command):
    try:
        process = subprocess.Popen(
            command,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout, stderr = process.communicate()
        output = stdout + stderr
        exit_code = process.returncode
        return {"id": job_id, "exit_code": exit_code, "output": output}
    except Exception as e:
        return {"id": job_id, "exit_code": -1, "output": str(e)}

def main():
    if len(sys.argv) != 2:
        print("Usage: python jobrunner.py <json_file>", file=sys.stderr)
        sys.exit(1)

    input_file = sys.argv[1]
    with open(input_file, "r") as f:
        jobs = json.load(f)

    existing_results = load_results()
    existing_ids = {r["id"] for r in existing_results}

    executed = 0
    skipped = 0
    active_commands = set()

    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = []
        for job in jobs:
            job_id = job["id"]
            if job_id in existing_ids:
                skipped += 1
                continue
            futures.append(executor.submit(process_job, job_id, job["command"]))

        for future in as_completed(futures):
            result = future.result()
            if result["id"] not in active_commands:
                active_commands.add(result["id"])
                save_results([result])
                executed += 1
            else:
                # Handle duplicate submission (shouldn't happen due to existing_ids check)
                pass

    print(f"{executed} {skipped}")

if __name__ == "__main__":
    main()
